    bubble_sort = BubbleSort(array1)
    print("Bubble Sort:", bubble_sort.sort())

    array2 = ['dog', 'cat', 'apple', 'banana', 'elephant']
    selection_sort = SelectionSort(array2)
    print("Selection Sort:", selection_sort.sort())
